<?php declare(strict_types=1);$d=$record??$old??[];$base=config('app.base_path');?><div class="card"><div class="form-grid"><div class="form-group full"><label>Package Title *</label><input name="title" required value="<?= htmlspecialchars((string)($d['title']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group"><label>Tourism Provider</label><select name="provider_id"><option value="">Independent / not assigned</option><?php foreach($providers??[] as $p):?><option value="<?= (int)$p['id']?>" <?= (string)($d['provider_id']??'')===(string)$p['id']?'selected':''?>><?= htmlspecialchars($p['legal_name'].' · '.$p['provider_type'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select name="status"><?php foreach(['Draft','Pending','Active','Inactive','Suspended'] as $v):?><option <?= ($d['status']??'Draft')===$v?'selected':''?>><?= $v?></option><?php endforeach;?></select></div><div class="form-group"><label>Duration (days)</label><input type="number" min="1" name="duration_days" value="<?= (int)($d['duration_days']??1)?>"></div><div class="form-group"><label>Nights</label><input type="number" min="0" name="duration_nights" value="<?= (int)($d['duration_nights']??0)?>"></div><div class="form-group"><label>Pricing</label><select name="pricing_type"><option value="PER_PERSON" <?= ($d['pricing_type']??'PER_PERSON')==='PER_PERSON'?'selected':''?>>Per person</option><option value="PER_GROUP" <?= ($d['pricing_type']??'')==='PER_GROUP'?'selected':''?>>Per group</option></select></div><div class="form-group"><label>Base Price (₹) *</label><input type="number" min="0" step="0.01" name="base_price" required value="<?= htmlspecialchars((string)($d['base_price']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group"><label>Discount Price (₹)</label><input type="number" min="0" step="0.01" name="discount_price" value="<?= htmlspecialchars((string)($d['discount_price']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group"><label>Max Travellers</label><input type="number" min="1" name="max_travellers" value="<?= htmlspecialchars((string)($d['max_travellers']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="form-group"><label>Cover Image</label><input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"></div><div class="form-group full"><label>Description</label><textarea name="description" rows="6"><?= htmlspecialchars((string)($d['description']??''),ENT_QUOTES,'UTF-8')?></textarea></div></div></div><style>.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.form-group.full{grid-column:1/-1}.form-group label{display:block;font-weight:600;margin-bottom:7px}.form-group input,.form-group select,.form-group textarea{width:100%;box-sizing:border-box}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.form-group.full{grid-column:auto}}</style>